public class EventuallyConsistentUserSession {
    private final ConcurrentHashMap<String, UserProfile> localCache = new ConcurrentHashMap<>();
    private final MessageQueue replicationQueue;

    public UserProfile readProfile(String userId) {
        // Returns potentially stale local replica immediately for high availability
        return localCache.getOrDefault(userId, fetchFromRemoteStore(userId));
    }

    public void updateProfile(UserProfile profile) {
        // 1. Write locally or to local partition primary
        localCache.put(profile.getId(), profile);

        // 2. Asynchronously propagate event to downstream replicas
        replicationQueue.publish(new ProfileUpdateEvent(profile));
    }

    private UserProfile fetchFromRemoteStore(String userId) {
        UserProfile remote = DatabaseClient.query(userId);
        if (remote != null) {
            localCache.put(userId, remote);
        }
        return remote;
    }
}
